const $=s=>document.querySelector(s);
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',back:'<path d="m14 5-7 7 7 7"/>',arrow:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m5 12 4 4L19 6"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2.3"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5ZM9 3v16M15 5v16"/>',book:'<path d="M12 5C9 3 5 3 3 4v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-2-1-6-1-9 1Zm0 0v15"/>',heart:'<path d="M12 20S3 14.5 3 8.7A4.7 4.7 0 0 1 12 6a4.7 4.7 0 0 1 9 2.7C21 14.5 12 20 12 20Z"/>',user:'<circle cx="12" cy="7" r="3.3"/><path d="M5 21v-2a7 7 0 0 1 14 0v2M8 15l4 3 4-3"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4V3Z"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',share:'<path d="M7 9H4v12h16V9h-3M12 15V2m-4 4 4-4 4 4"/>',coffee:'<path d="M4 8h12v6a6 6 0 0 1-12 0V8ZM16 9h2a3 3 0 0 1 0 6h-2M3 21h15M7 5V2m5 3V2"/>',camera:'<path d="M3 6h4l2-3h6l2 3h4v15H3V6Z"/><circle cx="12" cy="13" r="4"/>',photo:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 5-5 4 4 4-6 5 7"/>',edit:'<path d="m4 16 12-12 4 4L8 20l-5 1 1-5Zm10-10 4 4"/>',link:'<path d="m9 15 6-6M8 17l-2 2a4.2 4.2 0 0 1-6-6l5-5a4.2 4.2 0 0 1 6 0m2-1 2-2a4.2 4.2 0 0 1 6 6l-5 5a4.2 4.2 0 0 1-6 0" transform="translate(1 0)"/>',folder:'<path d="M3 6V4h6l3 3h9v13H3V6Z"/>',filter:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2" fill="var(--paper)"/><circle cx="16" cy="12" r="2" fill="var(--paper)"/><circle cx="10" cy="18" r="2" fill="var(--paper)"/>',layers:'<path d="m12 3 10 6-10 6L2 9l10-6Zm-9 11 9 5 9-5M3 18l9 5 9-5"/>',locate:'<path d="m21 3-7 18-3-8-8-3 18-7Z"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.1M3 12h.1M3 18h.1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v5m10-5v5M3 11h18M7 15h3m4 0h3M7 18h3"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z"/>',mountain:'<path d="m2 21 7-16 4 8 3-6 7 14H2ZM6 12l3 2 2-3m3 2 2 2 2-3"/>',award:'<circle cx="12" cy="9" r="6"/><path d="m7 14-1 8 6-3 6 3-1-8M12 6v6m-3-3h6"/>',lock:'<rect x="5" y="10" width="14" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 15v3"/>',cloud:'<path d="M6 18a5 5 0 0 1-.5-10 7 7 0 0 1 13.3-1A5.5 5.5 0 0 1 19 18M9 17l3 3 6-6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',upload:'<path d="M12 17V4m-5 5 5-5 5 5M4 17v4h16v-4"/>',settings:'<path d="m9 3 6 0 1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z"/><circle cx="12" cy="12" r="3"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',trash:'<path d="M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',redo:'<path d="M19 8a8 8 0 1 0 1 9M19 3v6h-6"/>',sort:'<path d="M4 6h16M4 12h11M4 18h6m8-4v8m-3-3 3 3 3-3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 3"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',leaf:'<path d="M20 3C9 2 3 9 6 16s14 3 14-13ZM4 21l12-13"/>',smile:'<circle cx="12" cy="12" r="9"/><path d="M8 9h.1M16 9h.1M7 13c1 6 9 6 10 0"/>'};
function I(n){return `<svg class="ico" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.star}</svg>`}
const A=n=>`assets/${n === 'city' ? 'shanghai' : n}.jpg`;
function go(id,b,c=''){return `<button class="${c}" data-go="${id}">${b}</button>`}
function check(on=true){return `<span class="check ${on?'on':''}">${on?I('check'):''}</span>`}
function pill(t,c=''){return `<span class="tag ${c}">${t}</span>`}
function primary(t,id,i=''){return go(id,`${i?I(i):''}${t}`,'primary')}
function secondary(t,id,i=''){return go(id,`${i?I(i):''}${t}`,'secondary')}
function section(t,l='',id=''){return `<div class="section-title"><h3>${t}</h3>${l?go(id,`${l}${I('arrow')}`,'text-btn'):''}</div>`}
function search(t='搜索我的收藏',id='search'){return go(id,`${I('search')}<span class="grow">${t}</span>`,'searchbar')}
function atlasTop(t,b='home',r='',id=''){return `<header class="topbar">${go(b,I('back'),'back')}<h2>${t}</h2><div class="right">${r?go(id,r):'<span style="width:24px"></span>'}</div></header>`}
function nav(a){return `<nav class="tabbar">${[['home','收藏','bookmark'],['map','地图','map'],['add','','plus'],['timeline','足迹','book'],['profile','我的','user']].map(([id,t,i])=>go(id,`${I(i)}${t?`<span>${t}</span>`:''}`,`tab ${id===a?'active':''} ${id==='add'?'add':''}`)).join('')}</nav>`}
function status(){return `<div class="status"><span class="status-time">9:41</span><span class="status-icons"><svg viewBox="0 0 17 12"><path d="M1 8h2v4H1zm4-3h2v7H5zm4-3h2v10H9zm4-2h2v12h-2z"/></svg><svg viewBox="0 0 17 12"><path d="M.5 3.5a13 13 0 0 1 16 0l-2 2a10 10 0 0 0-12 0zm4 4a6 6 0 0 1 8 0l-2 2a3 3 0 0 0-4 0zm3 3a1.5 1.5 0 1 1 3 0 1.5 1.5 0 0 1-3 0Z"/></svg><span class="battery"></span></span></div>`}
function phone(b,id){return `<article class="phone paper-texture" data-screen="${id}">${status()}${b}<div class="home-indicator"></div></article>`}
function page(t,b,{back='home',right='',rid='',dock='',cls=''}={}){return `${atlasTop(t,back,right,rid)}<main class="content ${cls}" style="${dock?'padding-bottom:110px':''}">${b}</main>${dock?`<div class="dock">${dock}</div>`:''}`}
function metrics(v=[['28','收藏地点'],['12','去过的地方'],['16','还想去']]){return `<div class="metrics">${v.map(([n,t])=>go(t==='去过的地方'?'timeline':t==='还想去'?'map':'collections',`<strong>${n}</strong><span>${t}</span>`,'metric')).join('')}</div>`}
const places=[{name:'Hidden Coffee',area:'徐汇区 · 咖啡馆',address:'梧桐路 128 号 · 上海',photo:'interior',state:'想去'},{name:'Mori Bake 森里',area:'静安区 · 甜品店',address:'安和路 36 号 · 上海',photo:'dessert',state:'想去'},{name:'一页书店',area:'徐汇区 · 独立书店',address:'云锦路 72 号 · 上海',photo:'bookshop',state:'去过'},{name:'Corner Café',area:'徐汇区 · 咖啡馆',address:'松风路 8 号 · 上海',photo:'cafe',state:'去过'}];
function placeRow(p=places[0],sm=false,id='place',extra=''){return go(id,`<img src="${A(p.photo)}" alt="${p.name}"><div class="grow"><h4>${p.name}</h4><p>${p.area}</p><div class="row gap6">${pill(p.state,p.state==='想去'?'orange':'green')}${extra}</div></div><span class="arrow">${I('arrow')}</span>`,`place-row ${sm?'small':''}`)}
function folderCard(t,p,n,id='folder'){return go(id,`<img src="${A(p)}"><div class="folder-label"><h4>${t}</h4><p>${n} 个地点</p></div>`,'folder-card')}
function hero(){return `<div class="hero-collage"><div class="subtext"><strong class="serif">收集生活里的<br>小小心动。</strong>把想去，慢慢变成去过。</div><div class="hero-back"></div><div class="hero-photo"><img src="${A('city')}"><span class="hand">A little city walk ♡</span></div><div class="hero-doodle hand">${I('leaf')} good things take time</div></div>`}
function home(){return `<main class="content with-nav"><div class="brand-row"><div class="brand english">My Little<br>Atlas <small style="font-size:14px;color:#9aa889">✧</small></div>${go('city',`${I('pin')} 全部城市 ${I('down')}`,'city-button')}</div>${search()}${hero()}${metrics()}<div class="chips">${go('collections','全部','chip active')}${go('map','想去 16','chip')}${go('timeline','去过 12','chip')}${go('visited','再去 5','chip')}</div>${section('我的收藏夹','全部','collections')}<div class="folder-grid">${folderCard('咖啡慢时光','cafe',8)}${folderCard('甜一点的日常','dessert',6)}${folderCard('城市漫游','city',7,'city-atlas')}</div>${section('最近收藏','查看全部','search')}${placeRow(places[0],true)}<div class="tiny muted center mt12">每一处心动，都值得好好收藏。</div></main>${nav('home')}`}
function mapArt(){return `<svg class="map-art" viewBox="0 0 390 844" preserveAspectRatio="xMidYMid slice"><defs><pattern id="blocks" width="89" height="91" patternUnits="userSpaceOnUse" patternTransform="rotate(-21)"><rect width="89" height="91" fill="#e9e4d3"/><path d="M8 8h30v29H8zm37 0h35v29H45zM8 46h30v37H8zm37 0h35v37H45z" fill="#e2dac5"/><path d="M0 0h89M0 0v91M41 0v91M0 41h89" stroke="#faf7ed" stroke-width="4"/></pattern></defs><rect width="390" height="844" fill="url(#blocks)"/><path d="M340-20C240 110 398 180 311 304S257 475 345 562 263 739 278 870" stroke="#bdcfd0" stroke-width="33" fill="none"/><path d="M-35 565 420 337M15-40 205 900M-30 236 430 631M-70 756 460 465" stroke="#d5c8ab" stroke-width="13" fill="none"/><path d="M-35 565 420 337M15-40 205 900M-30 236 430 631M-70 756 460 465" stroke="#faf5e3" stroke-width="9" fill="none"/><path d="m33 276 55-22 28 68-60 25Zm178 209 51-19 24 58-48 24ZM13 642l38-9 18 58-40 19Z" fill="#c9d3b4"/><text x="126" y="263" transform="rotate(-20 126 263)">梧 桐 路</text><text x="41" y="461" transform="rotate(-28 41 461)">安 和 路</text><text x="255" y="382" transform="rotate(77 255 382)">城 市 河 道</text><text x="161" y="586" transform="rotate(-24 161 586)">松 风 路</text><text x="54" y="303">口袋公园</text></svg>`}
function mapPage(){return `<div class="map-shell">${mapArt()}<span class="map-pin" style="left:72px;top:270px"></span><span class="map-pin orange" style="left:133px;top:337px"></span><span class="map-pin" style="left:55px;top:456px"></span><span class="map-pin orange" style="left:278px;top:465px"></span><span class="map-pin" style="left:174px;top:517px"></span>${go('place',`<img src="${A('interior')}">`,'photo-pin')}<div class="map-top">${search('上海 · 搜索我的地点')}<div class="chips">${go('map','全部','chip active')}${go('maplist','想去','chip')}${go('visited','去过','chip')}${go('maplist','再去','chip')}${go('filters',I('filter'),'chip')}</div></div><div class="map-legend"><span><i class="dot orange"></i>想去</span><span><i class="dot"></i>去过</span></div><div class="map-filters">${go('filters',I('layers'),'round')}${go('maplist',I('list'),'round')}</div>${go('permission',I('locate'),'round map-locate')}<div class="map-caption">示意地图 · 仅展示我的收藏</div><div class="map-card">${placeRow(places[0],false,'place',pill('1.2 km'))}<div class="map-action"><div class="grow hand" style="font-size:12px;color:#8b937d">想坐在窗边，慢慢喝一杯。</div>${primary('去这里','navigation','locate')}</div></div></div>${nav('map')}`}
function sheet(base,b){return `${base}<div class="sheet-overlay"><section class="sheet"><div class="sheet-handle"></div>${b}</section></div>`}
function placePage(v=false){return page('',`<div class="place-hero"><img src="${A('interior')}"><span class="label hand">a quiet corner in the city</span>${v?'<div class="date-slip"><strong>07</strong><span>Sat / 2026.11</span></div>':''}</div><div class="row between"><h1 class="place-title english">Hidden Coffee</h1>${pill(v?'去过 · 2 次':'想去',v?'green':'orange')}</div><div class="address">${I('pin')}<span>上海市 · 徐汇区<br>梧桐路 128 号（设计示例地址）</span><span class="grow"></span>${go('map',I('map'),'text-btn')}</div><div class="row mt12">${pill('咖啡馆')}${pill('窗边座位')}${pill('适合独处')}</div>${section('当初为什么想去')}<div class="note"><p class="hand" style="font-size:17px">街角很安静，窗边的光也刚刚好。<br>想挑一个不赶时间的下午来。</p></div>${v?`<div class="row between mt20"><span class="meta-row">${I('heart')}还想再去</span><button data-switch><span class="toggle on"></span></button></div>${section('我的到访','全部 2 次','timeline')}<div class="visit-mini">${go('journal','<span class="tiny muted">2026.11.07 · 第二次到访</span><p class="hand">阳光正好，很喜欢这家店。</p>')}<div class="row gap6"><img src="${A('coffee')}" style="height:53px;width:65px;object-fit:cover;border:3px solid #fffaf0"><img src="${A('interior')}" style="height:53px;width:65px;object-fit:cover;border:3px solid #fffaf0"></div></div>`:`${section('收在这里','管理','folder-picker')}<div class="row">${go('folder',`${I('folder')}咖啡慢时光`,'chip')}${go('folder',`${I('folder')}周末放空`,'chip')}</div>${section('灵感来源')}<div class="source-card"><div class="source-icon">${I('link')}</div><div class="grow"><strong>梧桐区的 5 家安静小店</strong><span>来源笔记 · 2026.11.05 收藏</span></div>${I('arrow')}</div>`}`,{back:v?'timeline':'map',right:I('share'),rid:'templates',dock:`<div class="bottom-split">${secondary('导航','navigation','locate')}${primary(v?'再记一次到访':'记一次到访','visit','edit')}</div>`})}
function poster(){return `<div class="poster paper-texture"><div class="poster-brand english">My Little Atlas</div><div class="poster-sub">A LITTLE MOMENT, WELL COLLECTED</div><div class="tape"></div><img class="poster-photo" src="${A('interior')}"><h3 class="english">Hidden Coffee</h3><div class="tiny muted">Shanghai · a quiet afternoon</div><p class="poster-quote hand">阳光正好，很喜欢这家店。</p><div class="stamp">${I('coffee')}<span>GOOD MOMENTS</span></div><div class="footnote">COLLECT A BETTER LIFE · MY LITTLE ATLAS</div></div>`}
const screens=[];
function add(id,name,group,entry,note,render){screens.push({id,name,group,entry,note,render})}add('welcome','欢迎与品牌',1,'首次打开','先感受产品，再开始收藏。',()=>page('',`<h1 class="welcome-title english"><span>My Little</span><span>Atlas <small style="font-size:20px;color:#a5af93">✧</small></span></h1><div class="welcome-collage"><img src="${A('city')}"><img src="${A('coffee')}"><span class="tape"></span><div class="stamp">${I('pin')}<span>MY OWN ATLAS</span></div><span class="script hand">Collect little joys ♡</span></div><p class="welcome-desc hand">把想去的地方，<br>慢慢变成去过的地方。</p><p class="tiny muted mt16">一本私人的城市收藏手账。<br>收藏心动，记录到访，留下自己的故事。</p>`,{back:'welcome',dock:primary('开启我的图鉴','city','arrow')}));
add('city','城市选择',1,'欢迎页／首页城市','可手动选城市，不强求定位。',()=>page('先从哪座城市开始？',`<div class="page-intro"><h1 class="serif">每座城市，<br>都有你的心动坐标。</h1><p>选择一座城市开始，之后随时可以切换。</p></div>${search('搜索城市','city')}<div class="card p16 mt16"><div class="row"><span style="color:#899775">${I('locate')}</span><div class="grow"><strong style="font-size:12px">使用当前位置</strong><p class="tiny muted" style="margin:5px 0 0">方便查看附近的收藏</p></div>${go('permission','开启','text-btn')}</div></div>${section('常用城市')}<div class="city-grid">${['全部城市','上海','杭州','苏州','北京','成都','广州','深圳','南京'].map((t,i)=>go('home',t,i===1?'active':'')).join('')}</div><div class="note mt24"><p class="tiny">不在这些城市？<br>你可以通过顶部搜索选择其他城市。</p></div>`,{back:'welcome',dock:primary('从上海开始','home')}));
add('home','收藏首页',1,'底部「收藏」','搜索、状态、主题和最近收藏。',home);
add('collections','全部收藏夹',1,'首页「我的收藏夹 → 全部」','主题分类；一个地点可加入多个夹。',()=>page('我的收藏夹',`${search('搜索收藏夹')}<div class="row between mt16 mb12"><span class="tiny muted">4 个主题 · 按最近更新</span>${go('bulk',`${I('sort')}整理`,'text-btn')}</div><div class="large-folder-grid">${folderCard('咖啡慢时光','cafe',8)}${folderCard('甜一点的日常','dessert',6)}${folderCard('城市漫游','city',7,'city-atlas')}${folderCard('一间小书店','bookshop',5)}${go('new-folder',`${I('plus')}新建收藏夹`,'new-folder')}</div><div class="note mt24"><p class="hand" style="font-size:17px">给每一种心动，<br>找一个喜欢的位置。</p></div>`,{right:I('plus'),rid:'new-folder'}));
add('folder','收藏夹详情',2,'收藏夹卡片','列表与地图切换；管理地点归类。',()=>page('我的主题收藏',`<div class="folder-cover"><img src="${A('cafe')}"></div><div class="folder-heading"><div class="row between"><h1 class="serif">咖啡慢时光</h1>${pill('仅自己可见','green')}</div><p>收集有阳光、有好咖啡的小角落。<br>8 个地点 · 4 个想去 · 4 个去过</p></div><div class="folder-toolbar">${secondary('地图查看','map','map')}${secondary('分享主题','folder-share','share')}</div><div class="chips">${go('folder','全部 8','chip active')}${go('folder','想去 4','chip')}${go('visited','去过 4','chip')}${go('bulk',I('sort'),'text-btn')}</div>${placeRow(places[0])}${placeRow(places[3],false,'visited',pill('想再去','green'))}${placeRow({...places[1],name:'Sunday Room',photo:'coffee',area:'静安区 · 咖啡馆'})}`,{back:'collections',right:I('more'),rid:'folder-options'}));
add('new-folder','新建收藏夹',2,'收藏夹右上角「＋」','名称必填；封面与样式有默认值。',()=>page('新建收藏夹',`<div class="folder-cover" style="height:180px"><img src="${A('city')}" style="height:154px"></div><div class="center">${go('photo-picker',`${I('photo')}更换封面`,'text-btn center')}<div class="palette"><span style="background:#e6dfcb" class="selected"></span><span style="background:#dbe2ce"></span><span style="background:#efd9bd"></span><span style="background:#dbe6e6"></span></div></div><div class="field-label">收藏夹名称 <small>4 / 20</small></div><div class="input"><input value="周末放空" aria-label="收藏夹名称"></div><div class="field-label">给它写一句话 <small>选填</small></div><div class="input textarea"><textarea rows="4" aria-label="收藏夹说明">留一些时间，给不赶路的下午。</textarea></div><div class="row mt20">${I('lock')}<span class="tiny muted">默认仅自己可见，分享时再选择展示内容。</span></div>`,{back:'collections',dock:primary('创建收藏夹','collections','plus')}));
add('search','搜索地点',2,'首页／地图搜索','先呈现自己的收藏，再找新地点。',()=>page('',`<div class="searchbar">${I('search')}<input value="Coffee" aria-label="搜索地点">${go('home',I('close'),'i-sm')}</div><div class="row between mt12"><span class="tiny muted">搜索范围：上海</span>${go('city','切换城市','text-btn')}</div>${section('我的收藏','2 个结果','folder')}${placeRow(places[0])}${placeRow(places[3],false,'visited',pill('想再去','green'))}<div class="divider-label">找一个新地点</div><div class="card p16"><div class="row"><span style="color:#8e9d7c">${I('pin')}</span><div class="grow"><strong style="font-size:12px">在上海搜索「Coffee」</strong><p class="tiny muted" style="margin:7px 0 0">搜索更多门店，确认分店后收藏</p></div>${go('branch',I('arrow'))}</div></div>${section('最近搜索')}<div class="chips">${go('folder','咖啡馆','chip')}${go('city-atlas','上海','chip')}${go('branch','书店','chip')}</div><div class="note mt24"><p class="tiny">没有找到想存的地方？<br>${go('manual','手动添加一个地点 →','text-btn')}</p></div>`,{back:'home'}));
add('add','添加操作菜单',2,'底部居中「＋」','三个明确任务，减少入口犹豫。',()=>sheet(home(),`<div class="row between"><h2 class="serif">收下一处心动</h2>${go('home',I('close'),'round')}</div><p class="subtitle">收藏现在的灵感，或写下刚刚的到访。</p>${[['import','link','导入地点','粘贴攻略文字、链接，或选择截图',''],['search','search','搜索添加','找到具体门店，放进我的收藏','blue'],['visit','edit','记录一次到访','选地点、留照片，写下今天的心情','peach']].map(([id,i,t,d,c])=>go(id,`<span class="menu-icon ${c}">${I(i)}</span><span class="grow"><strong>${t}</strong><p>${d}</p></span>${I('arrow')}`,'menu-option')).join('')}<div class="tiny muted center mt16">每一次出发，都是手账的新一页。</div>`));
add('import','导入灵感',3,'「＋ → 导入地点」','文字／链接／截图；保留来源。',()=>page('导入灵感',`<div class="steps"><span class="current"><i class="step-num">1</i> 放入灵感</span><i class="line"></i><span><i class="step-num">2</i> 挑选地点</span><i class="line"></i><span><i class="step-num">3</i> 收入图鉴</span></div><div class="page-intro"><h1 class="serif">心动的地方，<br>从这里收好。</h1><p>把攻略里的店，变成你的私人地点清单。</p></div><div class="field-label">粘贴文字或分享链接 ${go('import','粘贴','text-btn')}</div><div class="input textarea"><textarea rows="4" placeholder="把攻略正文或分享链接放在这里…" aria-label="导入内容">上海梧桐区的周末散步清单：
Hidden Coffee、Mori Bake 森里、
一页书店，还有街角那家咖啡馆。
想挑两家慢慢逛。</textarea></div><div class="divider-label">或者，换一种方式</div>${go('photo-picker',`${I('photo')}<span><strong>从截图里找地点</strong><span>选择相册截图，识别店名与地址</span></span>`,'upload')}<div class="notice mt20">${I('info')}<span>链接内容可能无法读取，可改贴正文或截图。识别结果需要你确认，不会自动收藏全部。</span></div>`,{back:'add',dock:primary('识别里面的地点','parsing','search')}));
add('parsing','识别进行中',3,'点击「识别里面的地点」','展示阶段与取消入口，保留输入。',()=>page('正在整理灵感',`<div class="center" style="padding-top:22px"><div class="empty-art"><span class="spark">✦</span><div class="empty-photo"><div class="inner">${I('search')}</div></div><span class="script hand">finding little places…</span></div><h1 class="serif empty-text">把心动，一个个找出来。</h1><p class="empty-desc">正在核对上海的门店信息，<br>稍后可以只挑你真正想去的地方。</p></div><div class="card p20"><div class="meta-row" style="margin-bottom:18px">${I('check')}已读取你放入的内容</div><div class="meta-row" style="margin-bottom:18px">${I('check')}找到了 4 个地点名称</div><div class="meta-row" style="color:#a78e65">${I('search')}正在核对城市与分店…</div><div class="progress mt20"><span style="width:68%"></span></div></div><p class="tiny muted center mt20">示意进度；点击继续查看结果。</p>`,{back:'import',dock:primary('查看识别结果','results')}));
add('results','导入结果与明确选择',3,'识别完成；图示为选中两项后的状态','选中的才保存；重复与待确认分开。',()=>page('挑选真正想去的地方',`<div class="steps"><span><i class="step-num">✓</i> 放入灵感</span><i class="line"></i><span class="current"><i class="step-num">2</i> 挑选地点</span><i class="line"></i><span><i class="step-num">3</i> 收入图鉴</span></div><div class="row between mb12"><span class="tiny muted" data-result-summary>找到 4 个地点 · 当前已选 2 个</span><span class="tiny muted">上海</span></div>${[[places[0],'已核对分店',true,'green'],[places[1],'已核对分店',true,'green'],[places[2],'已在收藏中',false,'blue']].map(([p,t,on,c])=>`<div class="result-item ${on?'selected':''}"><button data-toggle-check>${check(on)}</button><img src="${A(p.photo)}"><div class="grow"><strong>${p.name}</strong><p>${p.address}</p>${pill(t,c)} ${go(t==='已在收藏中'?'duplicate':'branch',t==='已在收藏中'?'查看已有地点':'更换分店','text-btn')}</div></div>`).join('')}<div class="result-item"><button data-toggle-check>${check(false)}</button><div class="grow"><strong>街角咖啡</strong><p>原文只有店名，暂时无法确认分店。</p>${pill('待确认地址','orange')}${go('branch','手动匹配门店 →','text-btn')}</div></div><div class="notice mt12">${I('info')}<span>初次识别不预选。这里只保存你明确选中的地点，重复地点保留已有记录。</span></div><div class="field-label">放进收藏夹 <small>可多选</small></div>${go('folder-picker',`${I('folder')}<span class="grow">周末放空</span>${I('arrow')}`,'input row')}`,{back:'import',dock:primary('收藏选中的 2 个地点','import-success','bookmark')}));
add('branch','分店匹配',3,'导入结果「更换／匹配分店」','用区域与完整地址区分同名门店。',()=>page('确认是哪一家',`${search('街角咖啡','branch')}<div class="row between mt12"><span class="tiny muted">当前城市：上海</span>${go('city','切换城市','text-btn')}</div><div class="notice mt12">${I('info')}<span>原文提到了「梧桐区」。请核对分店，避免存错位置。</span></div>${section('可能是这些门店')}<div class="result-item selected"><span class="option-dot on mt8"></span><div class="grow"><strong>街角咖啡 · 梧桐路店</strong><p>徐汇区 · 梧桐路 168 号<br>与原文区域一致</p>${pill('区域匹配','green')}</div></div><div class="result-item"><span class="option-dot mt8"></span><div class="grow"><strong>街角咖啡 · 云锦路店</strong><p>徐汇区 · 云锦路 52 号<br>另一家同名分店</p></div></div><div class="result-item"><span class="option-dot mt8"></span><div class="grow"><strong>街角咖啡 · 北岸店</strong><p>虹口区 · 北岸路 21 号<br>与原文区域不同</p></div></div><div class="rule"></div>${go('manual','没有找到？手动补充地址 →','text-btn')}${go('unlocated','先收藏，之后再定位 →','text-btn')}<div class="tiny muted mt20">门店与地址均为设计示例。</div>`,{back:'results',dock:primary('使用这家分店','results','check')}));
add('duplicate','重复地点处理',4,'导入时发现已收藏','保留原地点，可追加来源和归类。',()=>sheet(screens.find(s=>s.id==='results').render(),`<div class="row gap6 mb12"><span style="color:#8e9b7a">${I('bookmark')}</span><h2 style="margin:0" class="serif">这处心动，已经收好啦</h2></div><p class="subtitle">「一页书店」已在你的收藏中，原有记录会保留。</p>${placeRow(places[2],true,'visited')}<div class="row between mt16"><span class="tiny">追加这次的灵感来源</span><button data-toggle>${check(true)}</button></div><div class="row between mt20"><span class="tiny">同时加入「周末放空」</span><button data-toggle>${check(true)}</button></div>${primary('更新已有地点','results','check')}${go('visited','查看已有地点 →','text-btn center mt8')}`));
add('import-success','收藏完成',4,'确认选中地点后','明确保存数量，衔接地图和继续导入。',()=>page('已收入我的图鉴',`<div class="success-mark">${I('bookmark')}</div><h1 class="success-title serif center">又多了 2 处心动。</h1><p class="success-desc center">已加入「周末放空」<br>它们在地图上等着你的下一次出发。</p><div class="preview-ticket"><div class="row between mb12"><span class="english" style="font-size:15px">My next little adventure</span>${pill('想去','orange')}</div>${placeRow(places[0],true)}${placeRow(places[1],true)}<div class="tiny muted mt12 center">本次已收藏 2 个地点 · 来源已保存</div></div><div class="center hand mt24" style="font-size:20px;color:#899779">See you out there ♡</div>`,{back:'home',dock:`<div class="bottom-split">${secondary('继续导入','import')}${primary('去地图看看','map','map')}</div>`}));
add('manual','手动添加地点',4,'搜索无结果／分店匹配','地址与选点关联；允许后补定位。',()=>page('手动收下一处心动',`<div class="field-label">地点名称 <small>必填</small></div><div class="input"><input value="街角咖啡" aria-label="地点名称"></div><div class="field-label">城市与地址</div>${go('city',`<span class="grow">上海</span>${I('arrow')}`,'input row')}${go('branch',`${I('pin')}<span class="grow">搜索地址或在地图上选点</span>${I('arrow')}`,'input row mt8')}<p class="tiny muted">地址不确定时，可以先保存为待定位地点。</p><div class="field-label">分类 <small>选填</small></div><div class="chips">${go('manual','咖啡','chip active')}${go('manual','甜品','chip')}${go('manual','餐厅','chip')}${go('manual','更多','chip')}</div><div class="field-label">为什么想去 <small>选填</small></div><div class="input"><textarea rows="3" placeholder="记下心动的理由…" aria-label="想去理由"></textarea></div><div class="field-label">收藏夹 <small>选填</small></div>${go('folder-picker',`${I('folder')}<span class="grow">周末放空</span>${I('arrow')}`,'input row')}<div class="notice mt16">${I('info')}<span>未确认坐标的地点保存在收藏里，补齐定位后才出现在地图上。</span></div>`,{back:'branch',dock:primary('先收藏，之后补定位','unlocated','bookmark')}));
add('unlocated','待定位地点',4,'手动保存时没有地址','保存灵感，清楚提示尚未上地图。',()=>page('地点已收藏',`<div class="success-mark">${I('bookmark')}</div><h1 class="serif center success-title">先把心动留下。</h1><p class="success-desc center">「街角咖啡」已放进收藏。<br>地址补好以后，就能在地图上找到它。</p><div class="card p20 mt24"><div class="row between mb12"><strong class="serif" style="font-size:20px">街角咖啡</strong>${pill('待定位','orange')}</div><p class="tiny muted">城市：上海<br>地址：尚未确认<br>收藏夹：周末放空</p><div class="rule"></div><div class="meta-row hand" style="font-size:17px">想找个周末，慢慢逛。</div></div><div class="notice mt20">${I('pin')}<span>该地点暂不显示地图标记；在收藏夹中可以随时找到并补齐地址。</span></div><div class="mt16">${secondary('现在补齐地址','branch','pin')}</div><div class="center hand mt24 muted" style="font-size:21px">a little place, waiting for you</div>`,{back:'manual',dock:primary('回到我的收藏','collections')}));
add('map','私人地图',5,'底部「地图」','只看自己的地点；标记与卡片联动。',mapPage);
add('maplist','地图列表视图',5,'地图右侧「列表」','保留地图与筛选，按距离查看收藏。',()=>sheet(mapPage(),`<div class="row between"><h2 class="serif">附近的心动清单</h2>${go('map',I('map'),'round')}</div><p class="subtitle">上海 · 想去 · 按距离排序　共 10 个地点</p>${placeRow(places[0],false,'place',pill('1.2 km'))}${placeRow(places[1],false,'place',pill('1.8 km'))}${placeRow({...places[0],name:'Sunday Room',photo:'coffee',area:'静安区 · 咖啡馆'},false,'place',pill('2.6 km'))}<div class="tiny muted center mt16">只展示你收藏过的地点</div>`));
add('filters','地图筛选',5,'地图筛选按钮','状态、分类与收藏夹可组合筛选。',()=>sheet(mapPage(),`<div class="row between"><h2 class="serif">这次想看什么？</h2>${go('filters','重置','text-btn')}</div><div class="field-label">到访状态</div><div class="chips"><button class="chip" data-chip>全部</button><button class="chip active" data-chip>想去</button><button class="chip" data-chip>去过</button><button class="chip" data-chip>再去</button></div><div class="field-label">地点分类</div><div class="chips"><button class="chip active" data-chip>咖啡</button><button class="chip" data-chip>甜品</button><button class="chip" data-chip>餐厅</button><button class="chip" data-chip>书店</button></div><div class="field-label">收藏夹 <small>可多选</small></div><div class="row between" style="padding:10px 0"><span class="tiny">咖啡慢时光</span><button data-toggle>${check(true)}</button></div><div class="row between" style="padding:10px 0"><span class="tiny">周末放空</span><button data-toggle>${check(false)}</button></div><div class="notice mt16">${I('info')}<span>「再去」是去过后的额外标记，地点仍保留在「去过」中。</span></div>${primary('查看 4 个地点','map')}`));
add('navigation','选择导航方式',5,'地点卡或详情「导航」','交给常用地图导航，返回保留位置。',()=>sheet(placePage(),`<h2 class="serif">带我去这里</h2><p class="subtitle">Hidden Coffee · 梧桐路 128 号<br>外部导航将在你选择的地图 App 中打开。</p>${[['高德地图','pin'],['百度地图','map'],['系统地图','locate']].map(([t,i])=>`<button class="sheet-row" data-notice="效果图演示：实际 App 将打开${t}">${I(i)}<span class="grow">${t}</span>${I('arrow')}</button>`).join('')}<div class="row between mt16"><span class="tiny muted">记住这次的选择</span><button data-toggle>${check(false)}</button></div><div class="mt16">${secondary('取消','place')}</div>`));
add('place','想去的地点详情',6,'地图／搜索／收藏卡片','聚合地址、理由、归类和来源。',()=>placePage(false));
add('visited','去过的地点详情',6,'足迹／已到访地点','同一地点展示多次到访及再去意愿。',()=>placePage(true));
add('visit','记录一次到访',6,'地点详情／「＋ → 记录到访」','日期可改，照片与文字均可跳过。',()=>page('写下今天的小美好',`<div class="card p16 row"><img src="${A('interior')}" style="width:57px;height:57px;object-fit:cover;border-radius:8px"><div class="grow"><strong class="english" style="font-size:16px">Hidden Coffee</strong><p class="tiny muted" style="margin:6px 0 0">上海 · 徐汇区</p></div>${go('search','更换','text-btn')}</div><div class="field-label">到访日期 <small>可以补记以前的到访</small></div>${go('calendar',`${I('calendar')}<span class="grow">2026 年 11 月 7 日　周六</span>${I('arrow')}`,'input row')}<div class="field-label">今天拍到的 <small>选填 · 2 / 9</small></div><div class="photos">${['coffee','interior'].map(x=>`<div class="photo-edit"><img src="${A(x)}"><button data-notice="可在正式 App 中移除此照片">${I('close')}</button></div>`).join('')}${go('photo-picker',`${I('plus')}添加照片`,'add-photo')}</div><div class="field-label">一句话，记住今天 <small>选填</small></div><div class="input"><textarea rows="3" aria-label="到访感受" style="font-family:KaiTi,serif;font-size:17px">阳光正好，很喜欢这家店。
下次还想坐在这个窗边。</textarea></div><div class="row between mt20"><span class="meta-row">${I('heart')}还想再来</span><button data-switch><span class="toggle on"></span></button></div><p class="tiny muted mt16">保存后生成基础手账，可继续调整排版。</p>`,{back:'draft',right:'草稿',rid:'draft',dock:primary('留住这次到访','visit-success','check')}));
add('calendar','补记与日期选择',6,'记录页「到访日期」','明确日期，不默认导航即打卡。',()=>sheet(screens.find(s=>s.id==='visit').render(),`<div class="row between"><h2 class="serif">这次是哪一天？</h2>${go('calendar','回到今天','text-btn')}</div><p class="subtitle">可以补记过去的到访，未来日期不可选择。</p><div class="calendar-head">${I('back')}<span>2026 年 11 月</span>${I('arrow')}</div><div class="calendar-grid">${['一','二','三','四','五','六','日'].map(x=>`<span class="weekday">${x}</span>`).join('')}${[26,27,28,29,30,31].map(x=>`<span class="off">${x}</span>`).join('')}${Array.from({length:30},(_,i)=>`<span class="${i===6?'selected':i>6?'off':''}">${i+1}</span>`).join('')}</div><div class="notice mt16">${I('calendar')}<span>已选：2026 年 11 月 7 日 · 周六</span></div>${primary('确定日期','visit')}`));
add('visit-success','到访保存成功',7,'记录页「留住这次到访」','先完成记录，再邀请美化。',()=>page('新的一页，收好了',`<div class="success-mark">${I('check')}</div><h1 class="serif success-title center">这一天，值得留下。</h1><p class="success-desc center">Hidden Coffee · 第 2 次到访<br>你的照片和心情，已经变成一页手账。</p><div class="journal-cover mt24" style="height:235px"><img src="${A('coffee')}"><span class="caption hand">2026.11.07　阳光正好 ♡</span></div><div class="notice green mt24">${I('book')}<span>已收进「足迹」；地点详情同步更新为去过。你也可以继续美化这页手账。</span></div><div class="mt16">${secondary('继续美化排版','layout','edit')}</div><div class="center hand mt20" style="font-size:21px;color:#909c7e">one more lovely memory</div>`,{back:'visited',dock:primary('看看我的这页手账','journal','book')}));
add('journal','到访手账详情',7,'足迹卡片／保存到访后','保留照片与故事，分享和编辑清楚。',()=>page('我的手账',`<div class="journal-page"><div class="journal-date"><strong>07</strong><span>NOVEMBER<br>2026 · SATURDAY</span><span class="grow"></span>${pill('第 2 次到访','green')}</div><div class="journal-cover"><img src="${A('interior')}"><span class="caption hand">a slow afternoon in Shanghai</span></div><h1 class="english">Hidden Coffee</h1><div class="address">${I('pin')}上海 · 徐汇区 ${go('visited','查看地点 →','text-btn')}</div><div class="lined hand mt12">阳光正好，很喜欢这家店。<br>下次还想坐在这个窗边，<br>把咖啡喝完，再慢慢走回去。</div><div class="mini-collage"><img src="${A('coffee')}"><img src="${A('cafe')}"><div class="stamp">${I('coffee')}<span>GOOD MOMENTS</span></div></div><div class="row mt24">${pill('独处时光','green')}${pill('还想再来','orange')}</div></div>`,{back:'timeline',right:I('more'),rid:'record-options',dock:`<div class="bottom-split">${secondary('调整排版','layout','edit')}${primary('分享这份美好','templates','share')}</div>`}));
add('layout','手账排版编辑',7,'手账详情「调整排版」','模板、照片顺序与装饰；保留草稿。',()=>`${atlasTop('给回忆换个样子','journal','完成','journal')}<main class="content" style="padding-top:6px"><div class="row between mb12"><span class="tiny muted">当前：暖纸拼贴</span><span class="tiny muted">预览 · 竖版</span></div><div class="layout-preview">${poster()}</div></main><div class="layout-controls"><h4>把它变成喜欢的样子</h4><div class="row between">${[['templates','grid','模板'],['photo-picker','photo','照片'],['layout','edit','文字'],['layout','star','贴纸'],['layout','layers','纸张']].map(([id,i,t],n)=>go(id,`<span class="tool-box">${I(i)}</span>${t}`,`layout-tool ${n===0?'active':''}`)).join('')}</div></div><div class="dock">${primary('保存这页排版','journal','check')}</div>`);
add('photo-picker','选择照片',7,'记录添加照片／更换封面','照片选择数量明确，返回继续编辑。',()=>page('把照片放进这一页',`<div class="row between mb12"><span class="tiny muted">最近照片</span><span class="tiny muted">已选 2 张 · 最多 9 张</span></div><div class="photos" style="gap:7px">${['coffee','interior','city','cafe','dessert','bookshop','interior','coffee','city','dessert','bookshop','cafe'].map((x,i)=>`<button class="photo-edit" data-select-photo><img src="${A(x)}" style="height:107px;border-width:0;border-radius:4px;box-shadow:none"><span style="position:absolute;right:5px;top:5px">${check(i<2)}</span></button>`).join('')}</div><div class="notice mt20">${I('photo')}<span>此页展示照片选择的视觉状态。正式 App 调用系统相册，照片选择后可调整顺序。</span></div>`,{back:'visit',dock:primary('使用选中的 2 张照片','visit','check')}));
add('timeline','足迹时间线',8,'底部「足迹」','按日回忆；城市与月份都可切换。',()=>`<main class="content with-nav"><div class="brand-row"><div><div class="micro muted" style="letter-spacing:2px;margin:6px 0 7px">MY LITTLE JOURNAL</div><h1 class="serif" style="font-size:28px;margin:0">我的足迹</h1></div>${go('city-atlas',I('map'),'round')}</div><div class="stats-ticket"><h4 class="serif">慢慢走，也留下了很多。</h4>${metrics([['18','到访记录'],['12','去过的地方'],['3','探索城市']])}</div><div class="row between"><div class="chips">${go('timeline','时间线','chip active')}${go('city-atlas','城市图鉴','chip')}</div>${go('calendar','2026.11⌄','text-btn')}</div><div class="timeline"><div class="time-item"><div class="time-date"><strong>07</strong><span>NOV</span></div>${go('journal',`<img src="${A('interior')}"><h4 class="english">Hidden Coffee</h4><p class="hand">阳光正好，很喜欢这家店。</p><div class="meta"><span>上海 · 第 2 次到访</span><span>3 张照片</span></div>`,'time-card')}</div><div class="time-item"><div class="time-date"><strong>02</strong><span>NOV</span></div>${go('journal',`<img src="${A('bookshop')}"><h4>一页书店</h4><p class="hand">一本书，就能待一整个下午。</p><div class="meta"><span>上海 · 独处时光</span><span>2 张照片</span></div>`,'time-card')}</div></div></main>${nav('timeline')}`);
add('city-atlas','城市图鉴',8,'足迹「城市图鉴」／城市卡片','按城市汇总地点、到访与个人记忆。',()=>page('我的城市图鉴',`<div class="city-cover"><img src="${A('city')}"><div class="city-title"><h1 class="english">Shanghai</h1><span class="hand">上海 · 慢慢喜欢你</span></div></div>${metrics([['18','收藏地点'],['8','去过的地方'],['10','还想去']])}<div class="row between mt20 mb12"><h3 style="font-size:14px;margin:0">把足迹连成自己的地图</h3>${go('map','展开地图 →','text-btn')}</div>${go('map',`${mapArt()}<span class="map-pin" style="left:85px;top:35px"></span><span class="map-pin orange" style="left:170px;top:72px"></span><span class="map-pin" style="left:240px;top:25px"></span>`,'mini-map')}${section('在这座城，收集到的日常')}<div class="row between"><span class="tiny muted">咖啡馆　6 个</span><span class="tiny muted">书店　3 个</span><span class="tiny muted">散步　5 个</span></div>${section('最近的一页','更多','timeline')}${placeRow({...places[0],state:'去过'},true,'journal',pill('11.07'))}`,{back:'timeline',right:I('share'),rid:'city-share'}));
add('templates','选择分享模板',8,'手账／地点／图鉴「分享」','沿用当前内容，不要求重新填写。',()=>page('把这一页分享出去',`<div class="page-intro" style="margin:0 0 20px"><h1 class="serif" style="font-size:24px">选一个喜欢的样子。</h1><p>分享内容：Hidden Coffee · 这次到访</p></div><div class="template-grid">${[['暖纸拼贴','interior',''],['留白相册','coffee','white'],['城市来信','city','blue'],['自然小记','bookshop','sage']].map(([t,p,c],i)=>go('share',`<div class="thumb ${c}"><img src="${A(p)}"><strong>My Little Atlas</strong><div class="tiny-script hand">a little moment ♡</div>${i===0?`<span class="template-check">${check(true)}</span>`:''}</div><p>${t}</p>`,`template-option ${i===0?'active':''}`)).join('')}</div><div class="notice mt24">${I('lock')}<span>导出前可以隐藏精确日期、地址和私人备注。分享不会公开你的整个图鉴。</span></div>`,{back:'journal',dock:primary('用这个模板继续','share','arrow')}));
add('share','海报预览与隐私选项',8,'选择分享模板后','看到实际导出内容，再保存或分享。',()=>page('预览这一份美好',`${poster()}<div class="row between mt16"><span class="tiny">显示到访日期</span><button data-switch><span class="toggle"></span></button></div><div class="row between mt12"><span class="tiny">显示精确地址</span><button data-switch><span class="toggle"></span></button></div><div class="row between mt12"><span class="tiny">包含这次的文字小记</span><button data-switch><span class="toggle on"></span></button></div><div class="tiny muted mt16">当前预览：隐藏日期与精确地址。<br>此稿展示导出样式，开关可切换操作状态。</div>`,{back:'templates',dock:`<div class="bottom-split">${secondary('换模板','templates','grid')}${primary('保存到相册','saved','download')}</div>`}));
add('saved','导出完成与分享',9,'海报「保存到相册」','完成反馈；系统分享和继续浏览。',()=>page('美好，已经装好',`<div class="success-mark">${I('download')}</div><h1 class="serif center success-title">把这一页，带走。</h1><p class="success-desc center">海报导出完成的效果状态<br>可以发送给朋友，或留在自己的相册。</p><div style="transform:scale(.73);transform-origin:top center;height:337px;margin-top:25px">${poster()}</div><div class="row">${secondary('系统分享','system-share','share')}${secondary('回到手账','journal','book')}</div><p class="tiny muted center mt20">这里是设计演示，未实际向系统相册写入图片。</p>`,{back:'share',dock:primary('完成','journal','check')}));
add('folder-share','收藏夹与城市分享',9,'收藏夹／城市图鉴「分享」','集合海报自动带入主题与统计。',()=>page('分享我的一小片城市',`<div class="poster" style="height:492px"><div class="poster-brand english">My Little Atlas</div><div class="poster-sub">MY COFFEE COLLECTION</div><h2 class="serif center" style="font-size:23px;font-weight:500;margin:18px 0 10px">咖啡慢时光</h2><p class="hand center" style="font-size:15px;color:#829174">收集有阳光、有好咖啡的小角落。</p><img class="poster-photo" src="${A('cafe')}" style="height:197px">${metrics([['8','收藏地点'],['4','去过的地方'],['4','还想去']])}<div class="row center" style="justify-content:center;font-size:10px;color:#899073">${I('lock')}仅导出当前主题的统计与照片</div><div class="footnote">COLLECT A BETTER LIFE · MY LITTLE ATLAS</div></div><div class="row between mt20"><span class="tiny">显示地点名称清单</span><button data-switch><span class="toggle"></span></button></div><p class="tiny muted mt16">仅分享当前收藏夹；不包含其他私藏地点。<br>第一版导出静态海报，不附带无效二维码。</p>`,{back:'folder',dock:primary('保存主题海报','saved','download')}));
add('profile','我的图鉴',9,'底部「我的」','个人封面、统计、成就与设置。',()=>`<main class="content with-nav"><div class="row between" style="height:43px"><span class="micro muted">A PERSONAL ATLAS</span>${go('settings',I('settings'),'text-btn')}</div><div class="profile-cover"><img src="${A('city')}"><span class="tape"></span><span class="avatar">${I('user')}</span>${go('edit-profile','编辑封面','edit-cover')}</div><div class="profile-title"><h1 class="serif">小满的城市手账</h1>${go('edit-profile','编辑资料','text-btn')}</div><p class="profile-tagline hand">收集普通日子里的小小心动 ♡</p>${metrics([['28','收藏地点'],['12','去过的地方'],['3','探索城市']])}${section('我的小小成就','勋章墙','badges')}<div class="row between" style="padding:2px 6px 10px">${[['mountain','城市探索家','green'],['coffee','咖啡爱好者',''],['camera','留住光影','blue']].map(([i,t,c])=>go('badge-detail',`<span class="badge ${c}" style="width:76px;height:76px;border-radius:21px">${I(i)}</span><span class="tiny">${t}</span>`,'center')).join('')}</div>${[['timeline','book','我的到访记录','18 篇'],['city-atlas','map','我的城市图鉴','3 座城市'],['drafts','edit','未完成的草稿','1 篇'],['backup','cloud','备份与数据','查看状态']].map(([id,i,t,v])=>go(id,`${I(i)}<span class="grow">${t}</span><span class="value">${v}${I('arrow')}</span>`,'settings-row')).join('')}<p class="tiny muted hand center mt20">Collect a better life.</p></main>${nav('profile')}`);
add('badges','我的勋章墙',9,'我的「小小成就」','条件、数量与未解锁进度透明。',()=>page('我的小小成就',`<div class="page-intro"><h1 class="serif">走过的地方，<br>都会发一点光。</h1><p>已收集 4 枚勋章 · 慢慢探索就很好。</p></div><div class="segmented"><button class="active" data-chip>全部勋章</button><button data-chip>已获得 4</button><button data-chip>探索中</button></div><div class="badge-grid">${[['mountain','城市探索家','探索 3 座城市','green'],['coffee','咖啡爱好者','到访 5 家咖啡馆',''],['camera','留住光影','留下 10 张照片','blue'],['book','初见一页','写下第 1 篇手账','peach'],['star','百店俱乐部','12 / 100 家','locked'],['leaf','漫游收藏家','3 / 5 座城市','locked'],['sun','周末出走','4 / 8 个周末','locked'],['heart','念念不忘','2 / 5 家重访','locked'],['bookmark','心动收藏家','28 / 50 个地点','locked']].map(([i,t,d,c])=>go(c==='locked'?'badge-progress':'badge-detail',`<span class="badge ${c}">${I(i)}</span><strong>${t}</strong><p>${d}</p>`,'badge-cell')).join('')}</div><div class="note mt24"><p class="tiny">同一家店多次到访，只算一个探索地点。<br>不必赶进度，勋章会跟着生活慢慢亮起。</p></div>`,{back:'profile'}));
add('badge-detail','已获得的勋章',10,'勋章墙／我的成就','纪念获得时刻，回看走过的城市。',()=>page('一枚小小纪念',`<div class="badge-hero"><span class="spark" style="left:5px;top:25px">✧</span><span class="spark" style="right:0;bottom:18px">✦</span><span class="badge green">${I('mountain')}</span></div><h1 class="serif center success-title">城市探索家</h1><p class="tiny center" style="letter-spacing:2px;color:#99a184">CITY EXPLORER</p><p class="hand center" style="font-size:20px;line-height:1.9;color:#859273">不一样的街道，<br>都藏着一点喜欢。</p><div class="card p20 mt24"><div class="row between"><span class="tiny muted">解锁条件</span><span class="tiny">在 3 座城市留下到访</span></div><div class="rule"></div><div class="row between"><span class="tiny muted">获得时间</span><span class="tiny">2026 年 10 月 18 日</span></div><div class="row mt16">${pill('上海','green')}${pill('杭州','green')}${pill('苏州','green')}</div></div><div class="notice green mt20">${I('check')}<span>已收入你的勋章墙。更多探索故事，可以在城市图鉴里回看。</span></div>`,{back:'badges',dock:primary('看看我的城市图鉴','city-atlas','map')}));
add('badge-progress','未解锁勋章与进度',10,'勋章墙未解锁项','展示条件，不制造连续签到压力。',()=>page('慢慢探索中',`<div class="badge-hero"><span class="badge locked">${I('star')}</span></div><h1 class="serif center success-title">百店俱乐部</h1><p class="hand center" style="font-size:20px;line-height:1.9;color:#919780">生活的地图，<br>一处一处慢慢展开。</p><div class="card p20 mt24"><div class="row between"><strong style="font-size:13px;font-weight:500">到访 100 个不同地点</strong><span class="tiny muted">12 / 100</span></div><div class="progress mt16"><span style="width:12%"></span></div><p class="tiny muted mt16">同一地点的多次到访不会重复计数。<br>你每一次确认保存的到访，都会留下足迹。</p></div><div class="note mt24"><p class="hand" style="font-size:18px;line-height:1.8">不用为了勋章赶路。<br>好好感受，比数量更重要。</p></div>`,{back:'badges',dock:primary('看看还有哪些地方想去','map','map')}));
add('settings','设置',10,'我的右上角「设置」','账号、权限、数据与外观集中。',()=>page('设置',`<div class="divider-label">我的账号</div>${go('signin',`${I('user')}<span class="grow">登录与设备同步</span><span class="value">当前为本机使用${I('arrow')}</span>`,'settings-row')}${go('edit-profile',`${I('edit')}<span class="grow">个人资料</span><span class="value">${I('arrow')}</span>`,'settings-row')}<div class="divider-label">使用偏好</div>${go('permission',`${I('pin')}<span class="grow">系统权限</span><span class="value">定位、相册${I('arrow')}</span>`,'settings-row')}${go('navigation',`${I('locate')}<span class="grow">默认导航方式</span><span class="value">每次询问${I('arrow')}</span>`,'settings-row')}<div class="settings-row">${I('leaf')}<span class="grow">轻量装饰模式</span><button data-switch><span class="toggle"></span></button></div><div class="divider-label">数据与帮助</div>${[['backup','cloud','备份与数据',''],['backup','download','导出我的数据',''],['settings','info','关于 My Little Atlas','V 1.0'],['settings','lock','隐私与数据说明','']].map(([id,i,t,v])=>go(id,`${I(i)}<span class="grow">${t}</span><span class="value">${v}${I('arrow')}</span>`,'settings-row')).join('')}<p class="tiny muted center hand mt24">A personal atlas of places worth going.</p>`,{back:'profile'}));
add('backup','备份与数据',10,'我的／设置「备份与数据」','如实区分本机、备份文件与云同步。',()=>page('让回忆好好保存',`<div class="backup-status">${I('cloud')}<h3>回忆，目前保存在这台设备</h3><p>28 个地点 · 18 次到访 · 4 个收藏夹<br>最近本机备份：2026.11.06 20:18</p></div><div class="row between"><span class="tiny">本机数据占用</span><span class="tiny muted">128 MB</span></div><div class="storage-bar"><span></span><span></span></div><div class="storage-legend"><span><i class="dot"></i>照片 98 MB</span><span>记录 30 MB</span></div>${section('留一份自己的备份')}${go('backup',`${I('download')}<span class="grow">导出备份文件</span><span class="value">${I('arrow')}</span>`,'settings-row')}${go('backup',`${I('upload')}<span class="grow">从文件恢复</span><span class="value">${I('arrow')}</span>`,'settings-row')}${go('signin',`${I('user')}<span class="grow">登录并查看同步选项</span><span class="value">${I('arrow')}</span>`,'settings-row')}<div class="notice mt20">${I('info')}<span>当前原型的 JSON 备份不包含照片原文件。更换设备前，请同时保留原设备照片；完整媒体备份为后续开发项。</span></div><div class="notice green mt12">${I('lock')}<span>未登录的本机数据不会标为「已云同步」。云同步入口为后续功能规划。</span></div>`,{back:'settings'}));
add('empty','首次收藏空状态',11,'新用户进入收藏首页','有方向的空页，两个清晰起点。',()=>`<main class="content with-nav"><div class="brand-row"><div class="brand english">My Little<br>Atlas</div>${go('city',`${I('pin')} 上海 ${I('down')}`,'city-button')}</div>${search()}<div class="empty-art" style="margin-top:55px"><span class="spark">✦</span><div class="empty-photo"><div class="inner">${I('bookmark')}</div></div><span class="script hand">your story starts here ♡</span></div><h1 class="serif empty-text center">第一处心动，会在哪里？</h1><p class="empty-desc center">把攻略里想去的地方收进来，<br>慢慢拼成只属于你的城市图鉴。</p>${primary('导入一份心动清单','import','link')}<div class="mt12">${secondary('搜索一个地点','search','search')}</div><div class="note mt24"><p class="tiny">试试看：粘贴一段攻略文字，<br>然后只挑选你真正想去的那几家。</p></div></main>${nav('home')}`);
add('error','导入失败与替代路径',11,'链接读取失败','保留输入，给出可完成任务的方式。',()=>page('这份灵感，暂时没读到',`<div class="empty-art" style="margin-top:30px"><span class="spark">✧</span><div class="empty-photo"><div class="inner">${I('link')}</div></div><span class="script hand">let’s try another way</span></div><h1 class="serif empty-text center">换个方式，也能收好。</h1><p class="empty-desc center">分享链接需要登录，暂时无法读取。<br>你刚才的输入已保留，可以重试或换一种方式。</p><div class="card p16"><div class="meta-row">${I('link')}<span class="tiny">原分享链接已保留</span></div><p class="tiny muted" style="margin:10px 0 0">分享内容中的地点攻略链接</p></div><div class="stack mt20">${secondary('粘贴攻略正文','import','edit')}${secondary('从截图中找地点','photo-picker','photo')}${secondary('手动添加地点','manual','pin')}</div>`,{back:'import',dock:primary('重新尝试读取','parsing','redo')}));
add('permission','定位权限说明',11,'点击「定位／使用当前位置」','说明价值，拒绝后仍可使用地图。',()=>sheet(mapPage(),`<div class="row gap6 mb12"><span style="color:#869774">${I('locate')}</span><h2 class="serif" style="margin:0">看看心动离你有多远</h2></div><p class="subtitle">允许定位后，可以查看附近收藏与大致距离。<br>只在你使用相关功能时获取位置。</p><div class="notice green">${I('lock')}<span>不会因为靠近某地点自动打卡，也不会连续记录你的移动轨迹。</span></div>${primary('前往系统授权','map','locate')}<div class="mt12">${secondary('先手动选择城市','city','map')}</div><div class="tiny muted center mt16">拒绝定位后，仍可以搜索地点与浏览收藏地图。</div>`));
add('bulk','批量整理地点',11,'收藏夹「整理／多选」','移出当前夹与删除地点明确区分。',()=>page('整理「咖啡慢时光」',`<div class="row between mb12"><span class="tiny muted">已选 2 个地点</span><button class="text-btn" data-select-all>全选</button></div><div class="notice green mb12">${I('folder')}<span>移出本收藏夹后，地点和到访记录仍会留在你的图鉴中。</span></div><div class="selected-row">${[places[0],places[3],{...places[0],name:'Sunday Room',photo:'coffee'},{...places[0],name:'小院咖啡',photo:'city'}].map((p,i)=>`<div class="row"><button data-toggle>${check(i<2)}</button><div class="grow">${placeRow(p,false,i===1?'visited':'place')}</div></div>`).join('')}</div><p class="tiny muted mt24">一个地点能在多个收藏夹中。<br>「移出收藏夹」不会删除原地点与记录。</p>`,{back:'folder',right:'取消',rid:'folder',dock:`<div class="bulk-bar">${go('folder-picker',`${I('folder')}加入其他夹`)}${go('folder',`${I('bookmark')}移出本收藏夹`)}${go('delete',`${I('trash')}删除地点`)}</div>`}));
add('folder-picker','选择收藏夹',12,'导入／地点详情／批量整理','允许多选，支持就地新建。',()=>sheet(placePage(),`<div class="row between"><h2 class="serif">给心动找个位置</h2>${go('new-folder',`${I('plus')}新建`,'text-btn')}</div><p class="subtitle">一个地点可以放入多个收藏夹。</p>${[['咖啡慢时光','cafe',8,true],['甜一点的日常','dessert',6,false],['城市漫游','city',7,false],['周末放空','interior',2,true]].map(([t,p,n,on])=>`<div class="folder-list-item"><img src="${A(p)}"><div class="grow"><h4>${t}</h4><p>${n} 个地点</p></div><button data-toggle>${check(on)}</button></div>`).join('')}${primary('保存归类','place','check')}`));
add('draft','退出编辑与草稿',12,'未保存到访时返回','保护输入；继续、存草稿和放弃。',()=>sheet(screens.find(s=>s.id==='visit').render(),`<h2 class="serif">这一页，要先留着吗？</h2><p class="subtitle">照片和文字还没有存成正式到访，<br>可以先留为草稿，下次接着写。</p>${primary('保存草稿，稍后继续','profile','edit')}<div class="mt12">${secondary('继续写这一页','visit','arrow')}</div>${go('place','放弃本次编辑','text-btn center mt12')}<div class="tiny muted center mt12">草稿不会计入到访统计，也不会把地点标为去过。</div>`));
add('delete','删除地点确认',12,'批量整理／地点更多菜单','展示关联记录；删除前说明影响。',()=>`${placePage(true)}<div class="sheet-overlay"><div class="dialog"><div class="dialog-icon">${I('trash')}</div><h2 class="serif">要删掉这处心动吗？</h2><p>将从全部收藏夹中移除<br>Hidden Coffee，并删除关联的<br><strong>2 次到访记录和手账内容。</strong><br>这个操作无法撤销。</p>${go('home','删除地点与关联记录','primary danger-button')}<div class="mt12">${secondary('保留我的回忆','visited')}</div></div></div>`);
add('edit-profile','编辑个人资料',12,'我的「编辑资料／封面」','个人表达集中，不影响核心操作。',()=>page('让图鉴更像你',`<div class="profile-cover" style="height:154px;margin-bottom:53px"><img src="${A('city')}"><span class="avatar">${I('user')}</span>${go('photo-picker','更换封面','edit-cover')}</div><div class="field-label">图鉴名称 <small>7 / 20</small></div><div class="input"><input value="小满的城市手账" aria-label="图鉴名称"></div><div class="field-label">一句话介绍 <small>选填</small></div><div class="input"><textarea rows="3" aria-label="个人介绍">收集普通日子里的小小心动 ♡</textarea></div><div class="field-label">常住城市</div>${go('city',`<span class="grow">上海</span>${I('arrow')}`,'input row')}<div class="notice green mt24">${I('lock')}<span>资料用于个人图鉴与自愿分享的海报。你的地点清单默认仅自己可见。</span></div>`,{back:'profile',dock:primary('保存资料','profile','check')}));
add('signin','账号与登录规划',13,'设置「登录与设备同步」','先体验再登录；清楚标注后续能力。',()=>page('把图鉴带在身边',`<div class="center mt24"><div class="brand english" style="font-size:36px;line-height:1.1">My Little<br>Atlas</div><p class="hand" style="font-size:21px;color:#8c987c">属于你的城市，慢慢收藏。</p></div><div class="notice mt24">${I('info')}<span>账号与跨设备同步是后续开发能力。本稿展示入口与状态设计，当前 App 仍以本机保存和文件备份为准。</span></div><div class="field-label">手机号</div><div class="input row"><span style="padding-right:10px;border-right:1px solid var(--line)">+86</span><input placeholder="请输入手机号" aria-label="手机号"></div><div class="field-label">验证码</div><div class="input row"><input placeholder="输入验证码" aria-label="验证码"><button class="text-btn" data-notice="效果图演示，未发送验证码" style="white-space:nowrap">获取验证码</button></div><div class="row mt24" style="align-items:flex-start"><button data-toggle>${check(false)}</button><span class="tiny muted">阅读并同意用户协议与隐私说明后登录。<br>登录后再确认是否将本机图鉴合并到账号。</span></div>${go('profile','先继续本机使用 →','text-btn center mt24')}`,{back:'settings',dock:go('profile','登录功能规划预览','primary')}));
add('folder-options','收藏夹更多操作',13,'收藏夹右上角「更多」','编辑、批量整理、封面与删除分层。',()=>sheet(screens.find(s=>s.id==='folder').render(),`<h2 class="serif">整理这一份喜欢</h2><p class="subtitle">咖啡慢时光 · 8 个地点</p>${[['new-folder','edit','编辑名称与说明'],['photo-picker','photo','更换收藏夹封面'],['bulk','list','批量整理地点'],['folder-share','share','生成主题海报']].map(([id,i,t])=>go(id,`${I(i)}<span class="grow">${t}</span>${I('arrow')}`,'sheet-row')).join('')}<button class="sheet-row danger" data-notice="正式 App 中会确认删除收藏夹；地点与到访记录仍保留">${I('trash')}删除收藏夹</button><div class="tiny muted mt16">删除收藏夹只移除归类，不删除其中地点。</div>`));
add('record-options','到访记录更多操作',13,'手账详情右上角「更多」','编辑本次记录，与删除整个地点区分。',()=>sheet(screens.find(s=>s.id==='journal').render(),`<h2 class="serif">这一页的小设置</h2><p class="subtitle">Hidden Coffee · 2026.11.07 · 第 2 次到访</p>${[['visit','edit','修改这次到访'],['layout','grid','调整手账排版'],['templates','share','生成分享海报'],['visited','pin','查看地点与其他到访']].map(([id,i,t])=>go(id,`${I(i)}<span class="grow">${t}</span>${I('arrow')}`,'sheet-row')).join('')}<button class="sheet-row danger" data-notice="正式 App 会确认删除本次记录；其他到访与地点仍保留">${I('trash')}删除这次到访记录</button><div class="tiny muted mt16">删除一次到访，只影响这一篇记录。</div>`));
add('system-share','系统分享衔接',13,'海报导出后「系统分享」','用户主动选择目标，不自动发布。',()=>sheet(screens.find(s=>s.id==='saved').render(),`<div class="row gap6"><div style="height:52px;width:43px;background:#e7ddc3;padding:4px;border:2px solid #fffcf1"><img src="${A('interior')}" style="height:100%;width:100%;object-fit:cover"></div><div><h2 style="font-size:15px;margin-bottom:5px">我的城市手账 · 海报</h2><span class="tiny muted">一张图片 · 隐藏精确地址</span></div></div><div class="divider-label">系统分享界面示意</div><div class="row between" style="padding:10px 15px 18px">${[['share','发送给朋友'],['download','保存图片'],['folder','存储到文件']].map(([i,t])=>`<button class="layout-tool" style="width:82px" data-notice="分享效果演示，未向外部应用发送"><span class="tool-box">${I(i)}</span>${t}</button>`).join('')}</div><div class="notice green">${I('lock')}<span>分享需要你主动选择目标应用或联系人。此效果图不会向外部平台发布内容。</span></div><div class="mt16">${secondary('完成','journal')}</div>`));
const groups=[{id:1,title:'01 / 开始与收藏',subtitle:'从第一次打开，到看见属于自己的心动清单。'},{id:2,title:'02 / 整理与添加',subtitle:'主题收藏、搜索与三个明确的添加入口。'},{id:3,title:'03 / 灵感变地点',subtitle:'识别 → 核对分店 → 明确选择；收藏始终由你决定。'},{id:4,title:'04 / 保存与补全',subtitle:'重复不重建；地址不确定，也能先把灵感留下。'},{id:5,title:'05 / 地图与出发',subtitle:'在自己的收藏里选下一站，随手交给常用地图导航。'},{id:6,title:'06 / 地点与到访',subtitle:'同一个地点，保存每一次不一样的到访。'},{id:7,title:'07 / 手账与回忆',subtitle:'先轻松记录，再把照片和心情排成喜欢的样子。'},{id:8,title:'08 / 足迹与分享',subtitle:'按时间回看，按城市整理，只分享想展示的内容。'},{id:9,title:'09 / 个人图鉴',subtitle:'主题海报、个人封面与那些慢慢获得的小成就。'},{id:10,title:'10 / 成就与设置',subtitle:'有温度的反馈，也有清楚可靠的数据状态。'},{id:11,title:'11 / 必要状态',subtitle:'空白、失败、权限与批量整理，都有顺手的下一步。'},{id:12,title:'12 / 编辑与保护',subtitle:'归类、草稿、删除和个人表达，提前说明操作影响。'},{id:13,title:'13 / 补充入口',subtitle:'账号规划、更多操作及系统分享的衔接状态。'}];
const boards=[['welcome','city','home','collections'],['folder','new-folder','search','add'],['import','parsing','results','branch'],['duplicate','import-success','manual','unlocated'],['map','maplist','filters','navigation'],['place','visited','visit','calendar'],['visit-success','journal','layout','photo-picker'],['timeline','city-atlas','templates','share'],['saved','folder-share','profile','badges'],['badge-detail','badge-progress','settings','backup'],['empty','error','permission','bulk'],['folder-picker','draft','delete','edit-profile'],['signin','folder-options','record-options','system-share']];
function label(s,i){return `<div class="gallery-label"><span class="num">${String(i+1).padStart(2,'0')}</span><div><strong>${s.name}</strong><p>${s.entry}<br>${s.note}</p></div></div>`}
function get(id){return screens.find(s=>s.id===id)||screens.find(s=>s.id==='home')}
function gallery(g=0){document.body.className='';$('#app').innerHTML=`<header class="gallery-header"><div class="kicker">PRIVATE PLACES, PERSONAL STORIES · UI DESIGN / 2026</div><h1>My Little Atlas <em>我的城市收藏手账</em></h1><p>把想去的地方，慢慢变成去过的地方。<br>${screens.length} 个页面与状态 · 中文移动端 · 点击查看页面与核心动线</p><div class="header-meta">DESIGN EDITION 01<br>CREAM / SAGE / LITTLE JOYS<br>390 × 844 · 2026.11.07</div></header><nav class="gallery-controls">${go('home','体验完整动线','active')}${['全部页面',...groups.map(x=>x.title)].map((t,i)=>`<button data-group="${i}" class="${g===i?'active':''}">${t}</button>`).join('')}</nav><main class="gallery-grid">${screens.filter(s=>!g||s.group===g).map(s=>`<section class="gallery-item">${phone(s.render(),s.id)}${label(s,screens.indexOf(s))}</section>`).join('')}</main><footer class="gallery-footer">MY LITTLE ATLAS · COLLECT A BETTER LIFE<br>示例地点、距离与统计用于设计展示 · 地图为非地理示意底图 · 未连接真实账户与业务服务</footer>`}
function board(n){const g=groups[n-1],list=boards[n-1].map(get);document.body.className='board-mode';$('#app').innerHTML=`<main class="board"><header class="board-head"><div><div class="kicker">MY LITTLE ATLAS · DIGITAL SCRAPBOOK / UI EDITION 01</div><h1>${g.title}</h1></div><p>${g.subtitle}<br>390 × 844 · CREAM / SAGE · ${String(n).padStart(2,'0')} / ${boards.length}</p></header><section class="board-grid">${list.map(s=>`<div>${phone(s.render(),s.id)}${label(s,screens.indexOf(s))}</div>`).join('')}</section><footer class="board-foot"><span>把想去的地方，慢慢变成去过的地方。</span><span>2026.11.07 · 示例地点 / 氛围照片 / 非地理地图 · DESIGN ONLY</span></footer></main>`}
function overview(){document.body.className='board-mode';$('#app').innerHTML=`<main class="overview"><header class="board-head"><div><div class="kicker">PRIVATE PLACES, PERSONAL STORIES · COMPLETE UI COLLECTION / 01</div><h1><span class="english" style="font-size:42px">My Little Atlas</span>　我的城市收藏手账</h1></div><p>奶油纸白 × 鼠尾草绿 × 生活照片拼贴<br>${screens.length} 个页面与状态 · 收藏 → 出发 → 到访 → 手账 → 分享</p></header><section class="board-grid">${['home','map','place','results','journal','profile'].map(id=>{const s=get(id);return `<div class="overview-item"><div class="phone-wrap">${phone(s.render(),id)}</div>${label(s,screens.indexOf(s))}</div>`}).join('')}</section><div class="overview-caption">让每一处心动，都有自己的位置。<span class="hand" style="font-size:24px;color:#a7aa95">Collect little joys, one place at a time.</span></div><footer class="board-foot"><span>VISUAL SYSTEM / SOFT PAPER · PHOTO MEMORIES · QUIET INTERACTION</span><span>2026.11.07 · DESIGN EDITION 01</span></footer></main>`}
let current='home';
function prototype(id){document.body.className='';const s=get(id);$('#app').innerHTML=`<main class="prototype">${phone(s.render(),id)}<aside class="preview-info"><div class="overline">MY LITTLE ATLAS</div><h2>${s.name}</h2><p>${s.entry}<br>${s.note}<br><br>点击页面中的按钮，可体验核心页面衔接。<br>高保真设计演示，业务数据为静态示例。</p><button class="secondary" data-gallery>返回全部效果图</button><div class="preview-nav mt16"><button data-prev>上一页</button><button data-next>下一页</button></div></aside></main>`;history.replaceState(null,'',`#${id}`)}
const params=new URLSearchParams(location.search);
function render(){if(params.has('screen')){const s=get(params.get('screen'));document.body.className='single-mode';$('#app').innerHTML=phone(s.render(),s.id);return}if(params.has('board'))return board(Number(params.get('board')));if(params.has('overview'))return overview();if(location.hash){current=location.hash.slice(1);prototype(current)}else gallery()}
function toggleCheck(b){const c=b.querySelector('.check');if(c){c.classList.toggle('on');c.innerHTML=c.classList.contains('on')?I('check'):''}}
function updateResultSelection(b){const p=b.closest('.phone');if(!p)return;const n=p.querySelectorAll('.result-item .check.on').length;const sum=p.querySelector('[data-result-summary]');if(sum)sum.textContent=`找到 4 个地点 · 当前已选 ${n} 个`;const save=p.querySelector('.dock .primary');if(save){save.innerHTML=`${I('bookmark')}收藏选中的 ${n} 个地点`;save.disabled=n===0;save.style.opacity=n?1:.5}b.closest('.result-item')?.classList.toggle('selected',b.querySelector('.check').classList.contains('on'))}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go){current=b.dataset.go;prototype(current);return}if(b.hasAttribute('data-gallery')){history.replaceState(null,'',location.pathname);gallery();return}if(b.hasAttribute('data-group'))return gallery(Number(b.dataset.group));if(b.hasAttribute('data-prev')||b.hasAttribute('data-next')){const n=screens.findIndex(s=>s.id===current);current=screens[(n+(b.hasAttribute('data-next')?1:screens.length-1))%screens.length].id;prototype(current);return}if(b.hasAttribute('data-toggle')||b.hasAttribute('data-toggle-check')){toggleCheck(b);if(b.hasAttribute('data-toggle-check'))updateResultSelection(b);return}if(b.hasAttribute('data-switch')){b.querySelector('.toggle').classList.toggle('on');return}if(b.hasAttribute('data-chip')){b.classList.toggle('active');return}if(b.hasAttribute('data-select-photo')){toggleCheck(b);return}if(b.hasAttribute('data-select-all')){b.closest('.phone').querySelectorAll('.selected-row .check').forEach(c=>{c.classList.add('on');c.innerHTML=I('check')});return}if(b.dataset.notice){const t=document.createElement('div');t.style.cssText='position:fixed;bottom:35px;left:50%;transform:translateX(-50%);padding:14px 20px;background:#43533cf0;color:#fff8e9;border-radius:12px;font-size:12px;z-index:100;box-shadow:0 5px 20px #0002;max-width:80vw;text-align:center';t.textContent=b.dataset.notice;document.body.appendChild(t);setTimeout(()=>t.remove(),2600)}});
window.ATLAS_DESIGN={screens:screens.map(({id,name,group,entry,note})=>({id,name,group,entry,note})),boards,groups};window.addEventListener('hashchange',()=>{current=location.hash.slice(1)||'home';prototype(current)});
